import sys; sys.path.insert(0,'/tmp/work')
import diaphragm as D
import numpy as np
ND=(D.NX+1)*(D.NY+1)
diag_contribs=[]
# Replicate build_K but record
def nid(ix,iy): return iy*(D.NX+1)+ix
target=2*nid(1,0)+0
K=np.zeros((2*ND,2*ND))
def add_spring(nA,dofA,nB,dofB,k,tag):
    if 2*nA+dofA==target: diag_contribs.append((tag,'A',k))
    if 2*nB+dofB==target: diag_contribs.append((tag,'B',k))
Gp=12.0
# x-shear
for iy in range(D.NY+1):
    for ix in range(D.NX):
        has=False
        for cy in [iy-1,iy]:
            if 0<=cy<D.NY and D.cell_deck(ix,cy): has=True
        if has:
            k=Gp*D.DY/D.DX
            add_spring(nid(ix,iy),0,nid(ix+1,iy),0,k,'xshear')
# y-shear
for ix in range(D.NX+1):
    for iy in range(D.NY):
        has=False
        for cx in [ix-1,ix]:
            if 0<=cx<D.NX and D.cell_deck(cx,iy): has=True
        if has:
            k=Gp*D.DX/D.DY
            add_spring(nid(ix,iy),1,nid(ix,iy+1),1,k,'yshear')
# joist axial y
for ix in range(D.NX+1):
    for iy in range(D.NY):
        k=D.EA_JOIST/(D.DY*12)
        add_spring(nid(ix,iy),1,nid(ix,iy+1),1,k,'joist')
# girder axial x at girder lines
for iy in D.GIRDER_J:
    for ix in range(D.NX):
        k=D.EA_GIRDER/(D.DX*12)
        add_spring(nid(ix,iy),0,nid(ix+1,iy),0,k,'girder')
# edge
for ix in range(D.NX):
    k=D.EA_EDGE/(D.DX*12)
    add_spring(nid(ix,0),0,nid(ix+1,0),0,k,'edgeY0')
    add_spring(nid(ix,D.NY),0,nid(ix+1,D.NY),0,k,'edgeYN')
for iy in range(D.NY):
    k=D.EA_EDGE/(D.DY*12)
    add_spring(nid(0,iy),1,nid(0,iy+1),1,k,'edgeX0')
    add_spring(nid(D.NX,iy),1,nid(D.NX,iy+1),1,k,'edgeXN')
for t in diag_contribs: print(t)
print('sum',sum(k for _,_,k in diag_contribs))
"

